#!/usr/bin/env node
/**
 * scripts/restore-db.js
 *
 * Automated MongoDB restore script for InterviewOS.
 * - Restores a compressed archive generated by backup-db.js
 * - Requires explicit confirmation flag (--confirm) to guard against accidental production overwrites.
 *
 * Usage:
 *   node scripts/restore-db.js --archive backups/interviewos-backup-XXX.gz --confirm
 */

const { execSync } = require("child_process");
const fs = require("fs");
const path = require("path");

const args = process.argv.slice(2);
const hasConfirm = args.includes("--confirm");
const archiveIndex = args.indexOf("--archive");
const archiveFile = archiveIndex !== -1 ? args[archiveIndex + 1] : null;

const MONGO_URI =
  process.env.MONGO_URI || "mongodb://localhost:27017/interviewos";

console.log(`=======================================================`);
console.log(`♻️  InterviewOS MongoDB Restore Utility`);
console.log(`=======================================================`);
console.log(`Target URI:  ${MONGO_URI.replace(/:[^:@]+@/, ":****@")}`);
console.log(`Archive:     ${archiveFile || "None specified"}`);
console.log(`Confirmed:   ${hasConfirm ? "YES" : "NO"}`);
console.log(`-------------------------------------------------------\n`);

if (!archiveFile) {
  console.error("❌ Error: Missing --archive path. Example: node scripts/restore-db.js --archive backups/xxx.gz --confirm");
  process.exit(1);
}

const resolvedPath = path.resolve(archiveFile);
if (!fs.existsSync(resolvedPath)) {
  console.error(`❌ Error: Archive file not found at ${resolvedPath}`);
  process.exit(1);
}

if (!hasConfirm) {
  console.error("🚨 Safety Halt: Restoring a database snapshot will overwrite existing data!");
  console.error("   To proceed, append the '--confirm' flag to this command.");
  process.exit(1);
}

console.log(`🔄 Restoring from ${resolvedPath}...`);
try {
  execSync(
    `mongorestore --uri="${MONGO_URI}" --archive="${resolvedPath}" --gzip --drop`,
    { stdio: "inherit" }
  );
  console.log(`\n✅ Database restored successfully!`);
} catch (err) {
  console.error(`\n❌ Restore failed:`, err.message);
  process.exit(1);
}
